import math

import torch
from torch import nn

from recbole.model.general_recommender.bpr import BPR


class FreshCandidateModel(BPR):
    def __init__(self, config, dataset):
        super().__init__(config, dataset)

        self.embedding_dim = int(config["embedding_size"])
        self.num_capsules = 4
        self.mechanism_enabled = True
        self.conflict_enabled = True

        self.routing_layer = nn.Linear(self.embedding_dim, self.embedding_dim, bias=False)
        self.capsule_seeds = nn.Parameter(torch.empty(self.num_capsules, self.embedding_dim))
        self._reset_new_parameters()

        history_items, history_lens = self._build_history_tensors(dataset)
        self.register_buffer("history_items", history_items)
        self.register_buffer("history_lens", history_lens)

    def _reset_new_parameters(self):
        nn.init.xavier_uniform_(self.routing_layer.weight)
        nn.init.xavier_uniform_(self.capsule_seeds)

    def set_mechanism_enabled(self, enabled: bool):
        self.mechanism_enabled = bool(enabled)

    def set_conflict_enabled(self, enabled: bool):
        self.conflict_enabled = bool(enabled)

    def _build_history_tensors(self, dataset):
        history_data = dataset.history_item_matrix()
        if isinstance(history_data, tuple):
            if len(history_data) == 3:
                history_items, _, history_lens = history_data
            elif len(history_data) == 2:
                history_items, history_lens = history_data
            else:
                history_items = history_data[0]
                history_lens = None
        else:
            history_items = history_data
            history_lens = None

        if not isinstance(history_items, torch.Tensor):
            history_items = torch.as_tensor(history_items)
        history_items = history_items.long()

        if history_lens is None:
            history_lens = history_items.ne(0).sum(dim=1)
        elif not isinstance(history_lens, torch.Tensor):
            history_lens = torch.as_tensor(history_lens)
        history_lens = history_lens.long()

        return history_items, history_lens

    def _parent_score(self, user, item):
        user_e = self.user_embedding(user)
        item_e = self.item_embedding(item)
        score = torch.mul(user_e, item_e).sum(dim=1)
        return torch.nan_to_num(score)

    def _parent_full_sort_score(self, user):
        user_e = self.user_embedding(user)
        all_item_e = self.item_embedding.weight
        score = torch.matmul(user_e, all_item_e.transpose(0, 1))
        return torch.nan_to_num(score)

    def _compute_capsules(self, user):
        history_items = self.history_items[user]
        history_emb = self.item_embedding(history_items)
        history_mask = history_items.ne(0).float()

        projected = torch.tanh(self.routing_layer(history_emb))
        logits = torch.einsum("bld,kd->blk", projected, self.capsule_seeds)
        logits = logits / math.sqrt(float(self.embedding_dim))
        logits = logits.masked_fill(history_mask.unsqueeze(-1) == 0, -1e9)

        assign = torch.softmax(logits, dim=-1)
        assign = torch.nan_to_num(assign, nan=0.0, posinf=0.0, neginf=0.0)
        assign = assign * history_mask.unsqueeze(-1)

        capsules = torch.einsum("blk,bld->bkd", assign, history_emb)
        denom = assign.sum(dim=1).unsqueeze(-1).clamp_min(1e-12)
        capsules = capsules / denom
        capsules = torch.nan_to_num(capsules, nan=0.0, posinf=0.0, neginf=0.0)
        return capsules

    def _capsule_score(self, user, item):
        capsules = self._compute_capsules(user)
        item_e = self.item_embedding(item)
        capsule_scores = torch.einsum("bkd,bd->bk", capsules, item_e)

        support = capsule_scores.max(dim=1).values
        if self.conflict_enabled:
            conflict = torch.relu(-capsule_scores.min(dim=1).values)
            score = support - conflict
        else:
            score = support
        return torch.nan_to_num(score)

    def _capsule_full_sort_score(self, user):
        capsules = self._compute_capsules(user)
        all_item_e = self.item_embedding.weight
        capsule_scores = torch.einsum("bkd,nd->bkn", capsules, all_item_e)

        support = capsule_scores.max(dim=1).values
        if self.conflict_enabled:
            conflict = torch.relu(-capsule_scores.min(dim=1).values)
            score = support - conflict
        else:
            score = support
        return torch.nan_to_num(score)

    def calculate_loss(self, interaction):
        user = interaction[self.USER_ID]
        pos_item = interaction[self.ITEM_ID]
        neg_item = interaction[self.NEG_ITEM_ID]

        if self.mechanism_enabled:
            pos_score = self._capsule_score(user, pos_item)
            neg_score = self._capsule_score(user, neg_item)
        else:
            pos_score = self._parent_score(user, pos_item)
            neg_score = self._parent_score(user, neg_item)

        loss = self.loss(pos_score, neg_score)
        return torch.nan_to_num(loss)

    def predict(self, interaction):
        user = interaction[self.USER_ID]
        item = interaction[self.ITEM_ID]

        if self.mechanism_enabled:
            return self._capsule_score(user, item)
        return self._parent_score(user, item)

    def full_sort_predict(self, interaction):
        user = interaction[self.USER_ID]

        if self.mechanism_enabled:
            score = self._capsule_full_sort_score(user)
        else:
            score = self._parent_full_sort_score(user)
        return score.view(-1)
